from pathlib import Path
import json, shutil, zipfile, html, re
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
D = ROOT / 'final-design'
for p in D.glob('*.png'):
    if Image.open(p).format == 'JPEG':
        p.rename(p.with_suffix('.jpg'))
# The black proof retains a tinted tagline: keep it as a process study.
black = D / 'dum-e-odisha-final-black.jpg'
if black.exists():
    black.rename(D / 'process' / black.name)
old = ROOT / 'docs/identity.json'
archive = ROOT / 'docs/identity-round05.json'
if not archive.exists():
    shutil.copy2(old, archive)
palette = [
    {'name':'Deep chilli','hex':'#8B3029','role':'Primary lettering, lid and packaging band'},
    {'name':'Saffron','hex':'#E6AB44','role':'Separate E block, lid rim and limited packaging accents'},
    {'name':'Warm cream','hex':'#FFF9EF','role':'Main field and packaging substrate target'},
    {'name':'Charcoal','hex':'#29231F','role':'Functional copy outside the logo'}]
identity = {
    'brand_name':'Dum E Odisha','revision':'06','date':'2026-10-15',
    'display_lines':['DUM E','ODISHA'], 'tagline':'Flavour in Every Layer.',
    'category':'Biryani in different flavours and varieties',
    'positioning':'A warm, confident biryani specialist for everyday cravings and shared meals.',
    'structural_decision':'DUM in serif capitals; an independent saffron E block with a real gap; substantial sans-serif ODISHA below; compact separate lifting lid above.',
    'revision_basis':'User requested a more professional final design, deeper research and clear distinction between Dum and E.',
    'primary':'final-design/dum-e-odisha-final-logo.jpg',
    'reverse':'final-design/dum-e-odisha-final-white.jpg',
    'mockups':['final-design/dum-e-odisha-packaging-hero.jpg','final-design/dum-e-odisha-packaging-detail.jpg'],
    'palette':palette, 'palette_status':'Design targets; generated raster pixels vary. Not press specifications.',
    'typography':'Generated serif DUM and clean sans E/ODISHA. Supporting menus and information use a plain sans-serif; do not retype the logo or claim an exact font match.',
    'voice':'Warm, direct and appetite-led. Example: Find your favourite. Share a biryani.',
    'generation':'All new visual artwork and mockups generated through Nano Banana MCP.',
    'delivery_status':'Final visual direction in high-resolution JPEGs with opaque backgrounds. Not vector, transparent artwork, dielines or press-ready separations.',
    'research':'research/final-direction-research.md',
    'constraints':['Preserve DUM/E gap and E block','Odisha is integral to the brand name','BIRYANI is category copy outside the logo','Preserve earlier rounds as historical work','No trademark clearance or independently verified consumer testing claimed'],
    'qa_note':'Reverse proof preserves the E as a dark knockout. Black study excluded from final package because its tagline retains colour.'}
old.write_text(json.dumps(identity, indent=2)+'\n')

CSS = '''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#FFF9EF;color:#29231F;font:16px/1.65 Arial,sans-serif}a{color:#8B3029;text-underline-offset:4px}nav{display:flex;gap:24px;flex-wrap:wrap;border-bottom:1px solid #dacdbb;padding:22px 0}main{max-width:1240px;margin:auto;padding:0 36px 70px}.eyebrow{font-size:11px;letter-spacing:2.5px;text-transform:uppercase;font-weight:bold;color:#8B3029}header{padding:72px 0 42px}h1{font:normal clamp(44px,7vw,88px)/1.02 Georgia,serif;color:#8B3029;letter-spacing:-2px;margin:18px 0 28px}h2{font:normal clamp(30px,4vw,46px)/1.15 Georgia,serif;color:#8B3029;margin:12px 0 24px}h3{font-size:19px;line-height:1.3}p{max-width:760px}.lead{font-size:21px;max-width:700px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:32px}.intro{align-items:center}img{display:block;width:100%;height:auto}.logo{border:1px solid #eadfcd}.number{font-size:12px;letter-spacing:2px;color:#8B3029}section{border-top:1px solid #dacdbb;padding:48px 0;margin-top:24px}figure{margin:0}figcaption,.small{font-size:13px;color:#655e55;margin-top:12px}.panel{padding:30px;background:#f1e9da}.palette{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.swatch{height:105px;border:1px solid #dacdbb;margin-bottom:15px}.palette p{font-size:13px}.button{display:inline-block;background:#8B3029;color:#FFF9EF;padding:12px 20px;text-decoration:none;margin:8px 12px 8px 0}ul{padding-left:20px}li{margin:10px 0}footer{border-top:1px solid #dacdbb;padding-top:24px;font-size:13px}.wide{margin-top:32px}details{margin:20px 0}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid #dacdbb;padding:16px 12px;vertical-align:top}@media(max-width:700px){main{padding:0 20px 40px}.grid{grid-template-columns:1fr}.palette{grid-template-columns:1fr 1fr}header{padding-top:45px}nav{gap:16px}h1{letter-spacing:-1px}section{padding:32px 0}}@media print{nav,.button{display:none}section{break-inside:avoid}body{background:white}main{max-width:none;padding:0}}'''
def page(title, body):
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{CSS}</style></head><body><main>{body}</main></body></html>'
def pic(name, alt):
    p=D/name
    w,h=Image.open(p).size
    return f'<img src="final-design/{name}" alt="{html.escape(alt)}" width="{w}" height="{h}" loading="lazy">'
swatches=''.join(f'<article><div class="swatch" style="background:{p["hex"]}"></div><strong>{p["name"]}</strong><br><code>{p["hex"]}</code><p>{p["role"]}</p></article>' for p in palette)
body='''<nav aria-label="Brand guide"><a href="#identity">Identity</a><a href="#packaging">Packaging</a><a href="#system">Brand system</a><a href="brand-audit.html">Research & decisions</a><a href="brand-history.html">Earlier designs</a></nav>
<header><div class="eyebrow">Final identity · 15 October 2026 · Revision 06</div><h1>Dum E Odisha</h1><p class="lead">Flavour in Every Layer.</p><p>A clearer name. Warm, restrained colour. A consistent identity for the bag, the biryani tub and every shared meal.</p></header>
<div class="grid intro" id="identity"><figure class="logo">'''+pic('dum-e-odisha-final-logo.jpg','Final Dum E Odisha logo: DUM, a separated E in a saffron block, and ODISHA below')+'''</figure><div><div class="eyebrow">The final design</div><h2>Three parts.<br>One readable name.</h2><p><strong>DUM</strong> uses substantial serif capitals. <strong>E</strong> has its own saffron block and a clear gap from the M. <strong>ODISHA</strong> is large enough to read as part of the brand.</p><p>The lifting lid sits independently above the name. It recalls the warmth of opening a meal without joining the letters into “dume”.</p><p>Chilli provides depth; saffron gives the E a recognisable role. The separation remains visible in the reverse proof.</p><a class="button" href="final-design/dum-e-odisha-final-logo.jpg" download>Download final logo</a></div></div>
<section id="packaging"><div class="number">01 / In use</div><h2>Made to belong on the meal.</h2><p>The same name and colour hierarchy appear across the carrier, tub and seal. A quiet rice-grain pattern supports the packaging, leaving the logo easy to find.</p><figure>'''+pic('dum-e-odisha-packaging-hero.jpg','Photorealistic cream takeaway bag and biryani tub with matching chilli and saffron Dum E Odisha branding')+'''<figcaption>Takeaway family — paper carrier, lidded tub and sauce cup. Nano Banana concept mockup.</figcaption></figure><figure class="wide">'''+pic('dum-e-odisha-packaging-detail.jpg','Overhead packaging detail showing the separated DUM and E mark on the tub lid')+'''<figcaption>Lid and sleeve detail. These scenes demonstrate the identity; materials, food appearance and manufacturing specifications are illustrative.</figcaption></figure></section>
<section id="system"><div class="number">02 / Colour</div><h2>Two warm brand colours.</h2><div class="palette">'''+swatches+'''</div><p class="small">HEX values are design targets. The generated artwork has slight tonal variation; exact print inks require production artwork and a physical proof.</p></section>
<section><div class="number">03 / Recognition</div><h2>Keep the name intact.</h2><div class="grid"><div><h3>Name & hierarchy</h3><p>Always write <strong>Dum E Odisha</strong> in copy. Keep the space around E. Biryani describes the offer; place it in menu or product copy outside the official logo.</p><h3>Typography</h3><p>The logo combines generated serif lettering with clean sans-serif capitals. Use a quiet sans-serif for menu descriptions, prices and ordering information. Keep the supplied logo as artwork; retyping it will change its proportions.</p><h3>Voice</h3><p>Warm, direct and appetite-led. “Find your favourite. Share a biryani.” Lead with the dish and flavour; make recipe, sourcing or heritage claims only when the business can support them.</p></div><div class="panel"><h3>Application rules</h3><ul><li>Keep the DUM/E gap, E block and ODISHA line together.</li><li>Leave at least one E-block width of external space around the visible logo. This is a working layout rule.</li><li>Use a plain, contrasting field. Keep photos and patterns away from the lettering.</li><li>Do not stretch, crop, recolour individual letters or add shadows.</li><li>The tagline belongs at a readable size. A separately prepared no-tagline master is needed for smaller labels or avatars.</li><li>Check at the actual intended size before ordering print. No tested minimum size is claimed.</li></ul></div></div></section>
<section><div class="number">04 / Dark use</div><h2>The E stays distinct.</h2><div class="grid intro"><figure>'''+pic('dum-e-odisha-final-white.jpg','White Dum E Odisha reverse proof on black, with the E as a dark knockout in its separate white block')+'''</figure><div><p>The white reverse proof preserves the word gap and gives E a dark knockout inside its own block. Colour reinforces recognition; the structure carries it.</p><p class="small">Supplied as a JPEG on an opaque black background. A transparent reverse master and true single-ink separations belong to the production artwork stage.</p><a href="final-design/dum-e-odisha-final-white.jpg" download>Download reverse proof</a></div></div></section>
<section><div class="number">05 / Research & delivery</div><h2>A considered final direction.</h2><p>Seven primary studio case studies informed the decisions: clearer name structure, expressive logo lettering paired with practical information type, and a consistent packaging system. The result is our synthesis for this brand.</p><p><a href="brand-audit.html">Read the research and design decisions →</a></p><a class="button" href="final-design/dum-e-odisha-final-package.zip" download>Download final package</a><a href="brand-history.html">Browse all earlier designs →</a><p class="small">Package: colour logo, reverse proof, two packaging mockups, identity record and research notes. Visual artwork generated only through Nano Banana. High-resolution raster deliverables; editable vectors, transparent backgrounds and print dielines are not included.</p></section><footer>Dum E Odisha · Flavour in Every Layer. · Final visual direction, revision 06.</footer>'''
(ROOT/'brand-review.html').write_text(page('Dum E Odisha — Final brand guide',body))
sources=[('Jaani Maani Biryani — Bombay404','https://www.bombay404.com/work/jaanimaanibiryani','A clear logo and a wider illustrated packaging story can have different roles.'),('Raunaq — TAL','https://theartlogic.com/work/branding-visual-identity/','Decorative display type works alongside clean information type and a consistent system.'),('PizzaUP — Pentagram','https://www.pentagram.com/work/pizzaup/story','A short name component can be differentiated structurally.'),('Super Peach — Pentagram','https://www.pentagram.com/work/super-peach','Expressive lettering and illustration pair with disciplined supporting type.'),('Urban Tadka — Neat Work','https://neatworkstudio.com/project/urban-tadka/','The identity needs to work across delivery and physical packaging.'),('Biryani Blues — 4Design','https://www.4design.co.in/case-studies/biryani-blues','A restaurant identity extends consistently across packaging, stores and communication.'),('India Gate — ICARUS','https://icarus.co.in/work/indiagate','Regional product variants can retain a coherent parent brand.')]
rows=''.join(f'<tr><td><a href="{u}">{n}</a></td><td>{v}</td></tr>' for n,u,v in sources)
audit='''<nav><a href="brand-review.html">← Final brand guide</a><a href="brand-history.html">Earlier designs</a></nav><header><div class="eyebrow">Research & design decisions · Revision 06</div><h1>Clarity comes first.</h1><p class="lead">The previous logo blurred “Dum” and “E”. More colour could not repair that structural problem.</p></header><section><h2>What changed</h2><table><tr><th>Earlier design</th><th>Final design</th></tr><tr><td>Joined, flowing lowercase “dume”</td><td>DUM capitals and independent E block with real negative space</td></tr><tr><td>Lid crossing the wordmark</td><td>Compact lifting-lid emblem above the lettering</td></tr><tr><td>Odisha treated as a smaller signature</td><td>ODISHA is a substantial part of the full name</td></tr><tr><td>Several competing colour directions</td><td>Deep chilli and saffron with consistent packaging roles</td></tr></table></section><section><h2>Primary-source research</h2><p>Reviewed seven designer-published food identity case studies. These observations inform our original solution; the studios did not design or endorse Dum E Odisha.</p><table><tr><th>Studio case study</th><th>Relevant principle</th></tr>'''+rows+'''</table><p><a href="research/final-direction-research.md">Detailed research notes</a> · <a href="research/final-design-prompts.json">Generation prompts</a></p><p class="small">This is a design-reference review, not local competitor research, consumer testing or trademark clearance. Findings are based on published studio descriptions; commercial outcomes are not independently verified.</p></section><section><h2>Skills applied</h2><p>The eight supplied skill sources informed name architecture, typography, colour roles, source continuity, application checks and presentation hierarchy. The user's Nano Banana-only instruction governed all new visual generation. This round changes the earlier lettering structure in response to the latest request for a professional design and clear DUM/E separation.</p><p><a href="brand-audit-round05.html">Previous skill-by-skill audit</a> · <a href="brand-review-round05.html">Previous guide</a></p></section><section><h2>What was checked</h2><p>Visually reviewed the colour logo, reverse proof and both packaging images for name spelling, DUM/E separation, Odisha hierarchy and consistent colour placement. A black study retained a tinted tagline and was excluded from the final download package.</p><p>Files and local guide references are validated separately. Browser preview was unavailable, so no fresh browser-render check is claimed. The raster set establishes the final visual design; vector masters, exact ink separations and physical print proofs remain a production stage.</p></section>'''
(ROOT/'brand-audit.html').write_text(page('Dum E Odisha — Research and final decisions',audit))
history=ROOT/'brand-history.html'
content=history.read_text()
if 'id="round05"' not in content:
    block='''<section id="round05"><h2>Revision 05 — previous joined wordmark</h2><p>The corrected Dum E Odisha name was present, but the lowercase Dum/E junction remained unclear. Preserved as an earlier design, superseded by revision 06.</p><div class="grid"><article><img src="dum-e-odisha/dum-e-odisha-primary-tagline.jpg" alt="Previous joined lowercase Dum E Odisha wordmark"><a href="brand-review-round05.html">Open revision 05 guide</a></article><article><img src="dum-e-odisha/dum-e-odisha-identity-board.jpg" alt="Previous identity board preserved for history"><a href="brand-audit-round05.html">Previous audit</a></article></div></section>'''
    content=content.replace('<div class="eyebrow">DUM E BIRYANI',block+'<div class="eyebrow">DUM E BIRYANI',1)
    history.write_text(content)
files=['dum-e-odisha-final-logo.jpg','dum-e-odisha-final-white.jpg','dum-e-odisha-packaging-hero.jpg','dum-e-odisha-packaging-detail.jpg']
manifest={'brand':'Dum E Odisha','revision':'06','files':[], 'delivery_note':identity['delivery_status']}
for name in files:
    p=D/name
    im=Image.open(p)
    manifest['files'].append({'file':name,'width':im.width,'height':im.height,'format':im.format,'bytes':p.stat().st_size})
(D/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
with zipfile.ZipFile(D/'dum-e-odisha-final-package.zip','w',zipfile.ZIP_DEFLATED) as z:
    for name in files+['manifest.json']:
        z.write(D/name,name)
    z.write(old,'identity.json')
    z.write(ROOT/'research/final-direction-research.md','research.md')
    z.writestr('README.txt','DUM E ODISHA\nFlavour in Every Layer.\n\nFinal visual direction: revision 06, 15 October 2026.\nFour high-resolution JPEGs with opaque backgrounds, generated with Nano Banana MCP.\nKeep DUM and E separate; retain the E block and substantial ODISHA line.\nPalette targets: chilli #8B3029, saffron #E6AB44, cream #FFF9EF.\nThese are raster visual assets, not editable vector masters or print dielines.\nMockups are illustrative. Prepare production artwork and a physical proof before manufacture.\n')
print(json.dumps(manifest,indent=2))
